package cn.dot.budget;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class IndependentHealthReview {
 static int checks;
 interface Action {void run() throws Exception;}
 static void check(boolean b){checks++;if(!b)throw new AssertionError("check "+checks);}
 static void reject(Action a)throws Exception{checks++;try{a.run();}catch(IllegalArgumentException e){return;}throw new AssertionError("expected rejection "+checks);}
 @SuppressWarnings("unchecked") static Map<String,Object> obj(Object o){return (Map<String,Object>)o;}
 @SuppressWarnings("unchecked") static List<Object> arr(Object o){return (List<Object>)o;}
 static String envelope(Map<String,Object>a){Map<String,Object>message=new LinkedHashMap<>();message.put("role","assistant");message.put("content",AiJson.stringify(a));Map<String,Object>choice=new LinkedHashMap<>();choice.put("message",message);choice.put("finish_reason","stop");Map<String,Object>root=new LinkedHashMap<>();root.put("choices",Arrays.asList(choice));return AiJson.stringify(root);}
 static Map<String,Object> advice(String text){Map<String,Object>a=new LinkedHashMap<>();a.put("assessment",AiHealthHistory.facts(text).weeklyKg==null?"insufficient_data":"descriptive_only");a.put("takeaways",AiHealthHistory.supportedTakeaways(text));a.put("nextSteps",Arrays.asList("balanced_meals","professional_support"));return a;}
 static final class Store implements AiRememberedConsent.Store {int v=1;Set<String> grants=new HashSet<>(Arrays.asList("food_text","food_image","budget_text","statement_image"));public int version(){return v;}public boolean allowed(String s){return grants.contains(s);}public boolean write(String s){grants.add(s);return true;}public boolean clear(){grants.clear();return true;}public boolean empty(){return grants.isEmpty();}}
 public static void main(String[]args)throws Exception{
  AiHealthHistory.SendLimit limit=new AiHealthHistory.SendLimit();check(!limit.allow(-1));check(limit.allow(0));check(!limit.allow(0));check(!limit.allow(4999));check(limit.allow(5000));check(!limit.allow(4999));check(!limit.allow(9999));check(limit.allow(10000));check(!limit.allow(-1));check(limit.allow(Long.MAX_VALUE));check(!limit.allow(Long.MAX_VALUE));check(!limit.allow(0));

  for(String line:Files.readAllLines(Paths.get(args[0]),StandardCharsets.UTF_8)){
   Map<String,Object>fixture=obj(AiJson.parse(line));String text=AiJson.stringify(fixture.get("summary"));Map<String,Object>expected=obj(fixture.get("stats"));AiHealthHistory.Facts facts=AiHealthHistory.facts(text);check(facts.weightDays==((Number)expected.get("weightDays")).intValue());check(facts.spanDays==((Number)expected.get("spanDays")).intValue());check(facts.dietDays==((Number)expected.get("dietDays")).intValue());check(facts.completeDietDays==((Number)expected.get("completeDietDays")).intValue());check(facts.exerciseDays==((Number)expected.get("exerciseDays")).intValue());check(expected.get("weeklyKg")==null?facts.weeklyKg==null:Math.abs(facts.weeklyKg-((Number)expected.get("weeklyKg")).doubleValue())<1e-8);
   AiRequestContract request=new AiRequestContract(1,"food","health_history",0,"health-attempt",text);String body=AiPayloadBuilder.health(request,text);Map<String,Object>payload=obj(AiJson.parse(body));check(payload.keySet().equals(new HashSet<>(Arrays.asList("model","stream","max_tokens","thinking","response_format","messages"))));List<Object>messages=arr(payload.get("messages"));check(messages.size()==2);check("system".equals(obj(messages.get(0)).get("role")));check(text.equals(obj(messages.get(1)).get("content")));check(!body.contains("health-attempt"));check(((Number)payload.get("max_tokens")).intValue()==600);
   Store store=new Store();AiRememberedConsent consent=new AiRememberedConsent(store);check(!consent.allows(request));check(!consent.remember(request,false,consent.generation()));int oldGeneration=consent.generation();check(consent.remember(request,true,oldGeneration));check(consent.allows(request));final boolean[]cancelled={false};check(consent.revoke(()->cancelled[0]=true));check(cancelled[0]);check(!consent.allows(request));check(!consent.remember(request,true,oldGeneration));
   Map<String,Object>a=advice(text);check(AiResponseParser.parse(envelope(a),request).equals(AiJson.stringify(a)));Map<String,Object>extra=new LinkedHashMap<>(a);extra.put("prescription","dangerous instruction");reject(()->AiResponseParser.parse(envelope(extra),request));Map<String,Object>wrong=new LinkedHashMap<>(a);wrong.put("assessment",facts.weeklyKg==null?"descriptive_only":"insufficient_data");reject(()->AiResponseParser.parse(envelope(wrong),request));for(String code:AiHealthHistory.TAKEAWAYS)if(!AiHealthHistory.supportedTakeaways(text).contains(code)){Map<String,Object>bad=new LinkedHashMap<>(a);bad.put("takeaways",Arrays.asList(AiHealthHistory.supportedTakeaways(text).get(0),code));reject(()->AiResponseParser.parse(envelope(bad),request));}
   Map<String,Object>badSummary=AiHealthHistory.summary(text);badSummary.put("profile",Collections.singletonMap("age",42));reject(()->new AiRequestContract(1,"food","health_history",0,"bad-attempt",AiJson.stringify(badSummary)));reject(()->new AiRequestContract(1,"budget","health_history",0,"bad-attempt",text));reject(()->AiPayloadBuilder.text(request,text));reject(()->AiPayloadBuilder.health(request,text+" "));
   AiRequestSession session=new AiRequestSession();AiRequestSession.Ticket ticket=session.reserve(request);AiConsentSnapshot snapshot=new AiConsentSnapshot(ticket,text,t->AiPayloadBuilder.health(request,t));check(snapshot.text().equals(text));check(snapshot.payload().equals(body));AiRetryStore retry=new AiRetryStore();retry.offer(ticket,snapshot);session.release(ticket);AiRequestContract retryRequest=new AiRequestContract(1,"food","health_history",0,"retry-attempt",text,ticket.id);AiRequestSession.Ticket next=session.reserve(retryRequest);AiConsentSnapshot retried=retry.take(next);check(retried.matches(next));check(retried.payload().equals(body));check(!retry.availableFor(ticket.id));check(session.cancel(next,()->{}));check(!session.isCurrent(next));
  }
  System.out.println("PASS independent health review: "+checks+" JVM assertions; synthetic fixtures, no network or real health data.");
 }
}
